rule.sql:
SET 
    @serverTimeSec = floor(timestamp() / 1000),
    @timeDiff = abs(@serverTimeSec - deviceTime),
    @nowMs = timestamp(),
    @pad = concat('0000000000000', cast(@nowMs as String)),
    @lastSeenSortable = substring(@pad, length(@pad) - 13)

SELECT
  concat('Camera#', thingName) AS PK,
  'status' AS SK,

  false AS recording,

  @nowMs AS lastSeen,
  @timeDiff AS driftSec,

  sdCardInfo.present AS sdPresent,

  CASE sdCardInfo.present
    WHEN true THEN sdCardInfo.sizeMB
  END AS sdSizeMB,

  CASE sdCardInfo.present
    WHEN true THEN sdCardInfo.freeMB
  END AS sdFreeMB

  'Cameras#ALL' as camerasByLastSeenPk,
  concat(@lastSeenSortable , '#', thingName) as camerasByLastSeenSk

FROM 'yx/cameras/hello'
WHERE thingName = clientid()
